def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_moves = [h[0] for h in history]
    opp_moves = [h[1] for h in history]
    last_my = my_moves[-1]
    last_opp = opp_moves[-1]
    opp_c = opp_moves.count('C')
    opp_d = n - opp_c
    my_d = my_moves.count('D')

    if n >= 3 and opp_d == n:
        return 'D'

    if opp_c == n and n >= 5:
        return 'D'

    if n < 5:
        return 'C'

    opp_coop_rate = opp_c / n
    recent_opp = opp_moves[-5:]
    recent_opp_d = recent_opp.count('D')
    recent_my = my_moves[-5:]
    recent_my_d = recent_my.count('D')

    exploit_attempts = 0
    retaliations = 0
    for i in range(1, n):
        if my_moves[i-1] == 'D' and opp_moves[i-1] == 'C':
            exploit_attempts += 1
            if opp_moves[i] == 'D':
                retaliations += 1
    retaliation_rate = retaliations / exploit_attempts if exploit_attempts > 0 else 0.0

    if n >= 95:
        if retaliation_rate < 0.3:
            return 'D'
        if n == 99:
            return 'D'
        if n == 98 and retaliation_rate < 0.6:
            return 'D'

    if opp_d > 0.6 * n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_my_d >= 3 and opp_coop_rate > 0.5:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
        else:
            if opp_coop_rate > 0.7 and recent_opp_d <= 1:
                if rng.random() < 0.6:
                    return 'C'
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
